function makeCourse(name, hours) {
  return {
    name: name,
    hours: hours,
    describe() {
      return this.name + ' · ' + this.hours + '시간';
    },
    longer(other) {
      return other.hours > this.hours ? other.name : this.name;
    },
  };
}

// 이 함수는 그대로 두세요
function report(aName, aHours, bName, bHours) {
  const a = makeCourse(aName, aHours);
  const b = makeCourse(bName, bHours);
  return a.describe() + ' / ' + b.describe() + ' / 긴 쪽: ' + a.longer(b);
}
